<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import AdminShell from '@/layouts/AdminShell.vue'
import http, { getErrorMessage } from '@/api/http'
import type { Role, User } from '../types'

type WorkshopOption = { id: string; name: string }
type UserForm = { id?: string; username: string; email: string; password: string; role_ids: string[]; workshop_id: string; is_active: boolean }
const users = ref<User[]>([]); const roles = ref<Role[]>([]); const workshops = ref<WorkshopOption[]>([]); const query = ref(''); const error = ref(''); const saving = ref(false); const modalOpen = ref(false); const submitted = ref(false)
const empty = (): UserForm => ({ username: '', email: '', password: '', role_ids: [], workshop_id: '', is_active: true })
const form = ref<UserForm>(empty())
const editing = computed(() => Boolean(form.value.id))
const filteredUsers = computed(() => { const text = query.value.toLowerCase().trim(); return users.value.filter(user => !text || [user.username, user.email, ...user.roles.map(role => role.name)].some(value => value.toLowerCase().includes(text))) })
const activeCount = computed(() => users.value.filter(user => user.is_active).length)
async function load() { try { [users.value, roles.value, workshops.value] = await Promise.all([http.get<User[]>('/users').then(response => response.data), http.get<Role[]>('/roles').then(response => response.data), http.get<WorkshopOption[]>('/workshops/options').then(response => response.data)]) } catch (exception) { error.value = getErrorMessage(exception) } }
function openCreate() { form.value = empty(); submitted.value = false; error.value = ''; modalOpen.value = true }
function openEdit(user: User) { form.value = { id: user.id, username: user.username, email: user.email, password: '', role_ids: user.roles.map(role => role.id), workshop_id: user.workshop_id || '', is_active: user.is_active }; submitted.value = false; error.value = ''; modalOpen.value = true }
function valid() { const base = /^[a-zA-Z0-9_.-]{3,50}$/.test(form.value.username) && /.+@.+\..+/.test(form.value.email) && form.value.role_ids.length > 0; return editing.value ? base : base && /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d).{8,}$/.test(form.value.password) }
async function save() { submitted.value = true; if (!valid()) return; saving.value = true; error.value = ''; try { if (editing.value) { const { username, email, role_ids, workshop_id, is_active } = form.value; await http.patch(`/users/${form.value.id}`, { username, email, role_ids, workshop_id: workshop_id || null, is_active }) } else { await http.post('/users', { ...form.value, workshop_id: form.value.workshop_id || null }) }; modalOpen.value = false; await load() } catch (exception) { error.value = getErrorMessage(exception) } finally { saving.value = false } }
async function toggle(user: User) { error.value = ''; try { await http.patch(`/users/${user.id}`, { is_active: !user.is_active }); await load() } catch (exception) { error.value = getErrorMessage(exception) } }
onMounted(load)
</script>
<template><AdminShell><section class="page-heading"><div><p class="eyebrow">Identidad y acceso</p><h1>Usuarios</h1><p>Administra las cuentas, su estado y los roles asignados en el taller.</p></div><button class="primary-button" @click="openCreate">＋ Nuevo usuario</button></section><section class="metrics"><article><span>Usuarios totales</span><strong>{{ users.length }}</strong></article><article><span>Cuentas activas</span><strong>{{ activeCount }}</strong></article><article><span>Roles disponibles</span><strong>{{ roles.length }}</strong></article></section><p v-if="error" class="notice error">{{ error }}</p><section class="data-card"><div class="data-toolbar"><div><h2>Directorio de usuarios</h2><p>{{ filteredUsers.length }} resultado{{ filteredUsers.length === 1 ? '' : 's' }}</p></div><label class="search"><span>⌕</span><input v-model="query" placeholder="Buscar por nombre, correo o rol" /></label></div><div class="table-wrap"><table><thead><tr><th>Usuario</th><th>Roles</th><th>Estado</th><th class="align-right">Acciones</th></tr></thead><tbody><tr v-for="user in filteredUsers" :key="user.id"><td><strong>{{ user.username }}</strong><small>{{ user.email }}</small></td><td><span v-for="role in user.roles" :key="role.id" class="role-chip">{{ role.name.replace('_', ' ') }}</span></td><td><span class="status" :class="user.is_active ? 'status-active' : 'status-muted'">{{ user.is_active ? 'Activo' : 'Inactivo' }}</span></td><td class="align-right"><button class="table-action" @click="openEdit(user)">Editar</button><button class="table-action" :class="user.is_active ? 'danger-action' : ''" @click="toggle(user)">{{ user.is_active ? 'Desactivar' : 'Activar' }}</button></td></tr><tr v-if="!filteredUsers.length"><td colspan="4" class="empty-state">No encontramos usuarios con esos criterios.</td></tr></tbody></table></div></section><div v-if="modalOpen" class="modal-backdrop" @click.self="modalOpen = false"><section class="modal-card" role="dialog" aria-modal="true"><div class="modal-title"><div><p class="eyebrow">{{ editing ? 'Edición' : 'Nueva cuenta' }}</p><h2>{{ editing ? `Editar ${form.username}` : 'Crear usuario' }}</h2></div><button class="close-button" aria-label="Cerrar" @click="modalOpen = false">×</button></div><form class="modal-form" @submit.prevent="save"><label>Nombre de usuario<input v-model.trim="form.username" placeholder="Ej. juan.perez" /><span v-if="submitted && !/^[a-zA-Z0-9_.-]{3,50}$/.test(form.username)">Usa de 3 a 50 caracteres válidos.</span></label><label>Correo electrónico<input v-model.trim="form.email" type="email" placeholder="usuario@taller.com" /><span v-if="submitted && !/.+@.+\..+/.test(form.email)">Ingresa un correo válido.</span></label><label v-if="!editing">Contraseña<input v-model="form.password" type="password" placeholder="Contraseña temporal" /><span v-if="submitted && !/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d).{8,}$/.test(form.password)">Mínimo 8 caracteres, mayúscula, minúscula y número.</span></label><label>Roles<select v-model="form.role_ids" multiple size="5"><option v-for="role in roles" :key="role.id" :value="role.id">{{ role.name.replace('_', ' ') }}</option></select><span v-if="submitted && !form.role_ids.length">Selecciona por lo menos un rol.</span></label><label>Taller asignado<select v-model="form.workshop_id"><option value="">Sin taller asignado</option><option v-for="workshop in workshops" :key="workshop.id" :value="workshop.id">{{workshop.name}}</option></select><small>Obligatorio para Administrador y Recepcionista.</small></label><label v-if="editing" class="switch-row"><input v-model="form.is_active" type="checkbox" /> Cuenta activa</label><div class="modal-actions"><button type="button" class="secondary-button" @click="modalOpen = false">Cancelar</button><button class="primary-button" type="submit" :disabled="saving">{{ saving ? 'Guardando…' : 'Guardar cambios' }}</button></div></form></section></div></AdminShell></template>
